if (root == nullptr || level < 0) return 0;

std::queue<std::pair<Node*, int>> q;
q.push(std::make_pair(root, 0));

int count = 0;

while (!q.empty()) {
    auto current = q.front();
    q.pop();

    if (current.second == level) {
        count += current.first->keys.size();
    } else if (current.second < level) {
        for (const auto& child : current.first->children) {
            q.push(std::make_pair(child, current.second + 1));
        }
    }
}

return count;
// END_CODE

